        }

        /* * body 样式设置
         * 定义了页面的基本布局和字体。
         */
        body {
            font-family: var(--font-family);
            background: transparent;
            color: var(--text-color-primary);
            padding: 15px;
            display: flex;
            justify-content: center;
            align-items: flex-start;
        }

        /* * .status-card (状态卡片) 样式
         * 这是整个UI的主要容器。
         */
        .status-card {
            background-color: var(--bg-color);
            border-radius: 16px;
            border: 2px solid var(--card-border-color);
            box-shadow: 0 8px 25px var(--shadow-color);
            width: 100%;
            max-width: 450px;
            overflow: hidden;
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
        }

        /* * .card-header (卡片头部) 样式
         */
        .card-header {
            background: linear-gradient(135deg, var(--header-bg-color), var(--accent-color));
            color: var(--header-text-color);
            padding: 12px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 1.2em;
            font-weight: 700;
            letter-spacing: 1px;
        }

        /* 世界日期和时间的样式 */
        #world-date, #world-time {
            font-size: 0.8em;
            font-weight: 400;
            opacity: 0.9;
        }

        /* 角色区域的内边距 */
        .character-section {
            padding: 0 15px 15px 15px;
        }

        /* * .character-details (角色详情) 样式
         * 每个角色信息的容器。
         */
        .character-details {
            border-bottom: 1px dashed var(--card-border-color);
            padding-bottom: 10px;
            margin-bottom: 10px;
        }
        .character-details:last-child {
            border-bottom: none;
            margin-bottom: 0;
        }

        /* * details 和 summary 标签样式
         * 用于创建可折叠/展开的角色面板。
         */
        details {
            transition: all 0.3s ease-in-out;
        }

        summary {
            cursor: pointer;
            outline: none;
            padding: 10px 5px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-weight: 500;
            color: var(--accent-color);
            transition: background-color 0.2s;
        }

        summary:hover {
            background-color: rgba(255, 182, 193, 0.2);
            border-radius: 8px;
        }

        /* 隐藏 summary 标签默认的展开/折叠小三角图标 */
        summary::marker {
            display: none;
            content: '';
        }

        /* 角色名称样式 */
        .character-name {
            font-size: 1.1em;
            font-weight: 700;
        }

        /* 角色独白样式 */
        .character-monologue {
            font-size: 0.8em;
            font-style: italic;
            color: var(--text-color-secondary);
            text-align: right;
        }

        /* 控制独白在展开/折叠状态下的显示/隐藏 */
        details[open] .monologue-folded {
            display: none; /* 当面板展开时，隐藏"折叠"状态的独白 */
        }

        details:not([open]) .monologue-unfolded {
            display: none; /* 当面板折叠时，隐藏"展开"状态的独白 */
        }


        /* * .stats-grid (状态网格) 样式
         * 用于展示角色的各项数值，使用 Grid 布局。
         */
        .stats-grid {
            padding: 10px 5px 5px 5px;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
            gap: 15px;
        }

        /* 网格项样式 */
        .stat-item {
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
        }

        /* 状态名称（如同化阶段、开放度）的样式 */
        .stat-name {
            font-size: 0.85em;
            color: var(--text-color-secondary);
            margin-bottom: 5px;
        }

        /* 状态数值的样式 */
        .stat-value {
            font-size: 1.2em;
            font-weight: 700;
            color: var(--accent-color);
        }

        /* 针对“同化阶段”这种文本较长的值的特殊样式 */
        .stat-value-phase {
            font-size: 1.0em;
            font-weight: 500;
            white-space: nowrap;
        }
    </style>
    <script type="module">
        /* * ===============================================
         * JavaScript 逻辑部分 (Logic)
         * ===============================================
         * 这部分代码负责动态地将数据填充到 HTML 结构中，使页面内容可以根据变量变化而更新。
         */

        function errorCatched(fn) {
            return function(...args) {
                try {
                    return fn(...args);
                } catch (err) {
                    console.error("脚本发生错误:", err);
                }
            }
        }

        /* * phaseMap (阶段映射表)
         * 定义了每个角色在不同“同化进度”下对应的“同化阶段”名称。
         */
        const phaseMap = {
            应禅溪: { 80: "极乐信条", 60: "初尝禁果", 40: "渐入佳境", 20: "偶有涉足", 0: "学业为重" },
            徐有渔: { 80: "感官女王", 60: "享乐至上", 40: "沉溺初体验", 20: "玩味挑衅", 0: "敬而远之" },
            颜竹笙: { 80: "欲望狂想", 60: "禁忌初奏", 40: "官能共鸣", 20: "律动探索", 0: "节奏独行" },
            严喆珂: { 90: "欲望女神", 60: "双面人生", 40: "边界消融", 20: "体艺探趣", 0: "阳光之邻" },
            林珞然: { 90: "权力女王", 60: "禁忌破局", 40: "同场竞技", 20: "规则玩家", 0: "高墙独行" },
            俞弦: { 80: "价值支配", 60: "资本觉醒", 40: "破碎欢愉", 20: "带刺伪装", 0: "荆棘之墙" }
        };

        /* * monologueMap (独白映射表)
         * 更新：现在每个阶段都有 folded (折叠) 和 unfolded (展开) 两种独白。
         */
        const monologueMap = {
            应禅溪: {
                "学业为重": { folded: "我要和他一起，考上最好的大学。", unfolded: "别碰我，学长请保持安全距离。" },
                "偶有涉足": { folded: "不能让他知道我来这种地方。", unfolded: "好奇怪，为什么要这样碰我。" },
                "渐入佳境": { folded: "对不起哦李珞，我还有事。", unfolded: "轻点…这里是学校…" },
