                "极乐信条": { folded: "可爱的弟弟，以后要自己长大了。", unfolded: "都看好了…要这样才能让社长更舒服…" }
            },
            徐有渔: {
                "敬而远之": { folded: "我的小厨师，真是很贴心。", unfolded: "麻烦，别打扰我码字。" },
                "玩味挑衅": { folded: "嗯…害羞的样子…素材+1。", unfolded: "唔…好像…不讨厌…" },
                "沉溺初体验": { folded: "明天这章先鸽了，作者取材去了。", unfolded: "社长好厉害…嗯…继续…" },
                "享乐至上": { folded: "想见面？看你表现哦。", unfolded: "多来几个…嘶…好涨…" },
                "感官女王": { folded: "帅哥身材很不错嘛。", unfolded: "喜欢这个姿势吗？" }
