                "带刺伪装": { folded: "只有在他身边，我才能喘口气。", unfolded: "身体…为什么在发抖…" },
                "破碎欢愉": { folded: "只是…社团的额外补助。", unfolded: "进来吧…说好…就这一次…" },
                "资本觉醒": { folded: "老板，喜欢我…还是喜欢我的画？", unfolded: "上面和下面…感觉都好满…比陈着大多了" },
                "价值支配": { folded: "老公，我会永远爱你。", unfolded: "对…都给我…陈着不在…不用怜惜我…" }
            }
        };

        /**
         * 根据角色名和进度值，从 phaseMap 中获取对应的阶段名称。
         */
        function getPhaseName(characterName, progress) {
            const progressNum = parseInt(progress, 10) || 0;
            const thresholds = Object.keys(phaseMap[characterName]).sort((a, b) => b - a);
            for (const threshold of thresholds) {
                if (progressNum >= parseInt(threshold, 10)) {
                    return phaseMap[characterName][threshold];
                }
            }
            return "未知阶段";
        }

        /**
         * 填充数据函数。
         */
        function populateData() {
            const all_variables = getAllVariables(); 
            const stat_data = _.get(all_variables, 'stat_data', {});

            $('#world-date').text(_.get(stat_data, '世界.当前日期', '未知日期'));
            $('#world-time').text(_.get(stat_data, '世界.当前时间', '未知时间'));

            const characters = ['应禅溪', '徐有渔', '颜竹笙', '严喆珂', '林珞然', '俞弦'];
            characters.forEach(name => {
                const charData = _.get(stat_data, name, {});
                const progress = _.get(charData, '同化进度', 0);
                const openness = _.get(charData, '开放度', 0);
                const conviction = _.get(charData, '信服度', 0);

                const phaseName = getPhaseName(name, progress);

                // 根据阶段名称获取对应的独白对象 {folded: "...", unfolded: "..."}
                const monologue = _.get(monologueMap, [name, phaseName], { folded: "...", unfolded: "..." });

                const $details = $(`#${name}-details`);
                const $monologueContainer = $details.find('.character-monologue');

                // 更新 folded 和 unfolded 两种状态的独白内容
                $monologueContainer.find('.monologue-folded').text(monologue.folded);
                $monologueContainer.find('.monologue-unfolded').text(monologue.unfolded);

                $(`#${name}-phase`).text(phaseName);
                $(`#${name}-openness`).text(openness);
                $(`#${name}-conviction`).text(conviction);
            });
        }

        /**
         * 初始化函数。
         */
        function init() {
            populateData();
        }

        $(() => {
            errorCatched(init)();
        });
    </script>
