主线事件系统:
  rule:
    - 系统会自动判断并触发主线事件。分为随机主线事件和特定剧情事件。
  status:
    当前主线事件ID: {{get_message_variable::stat_data.世界.当前主线事件ID}}
    当前主线事件阶段: {{get_message_variable::stat_data.世界.当前主线事件阶段}}
    主线事件冷却计数: {{get_message_variable::stat_data.世界.主线事件冷却计数}}

<%_
const 主线事件库 = {
  全国舞蹈大赛: '一年一度的全国高中生舞蹈大赛即将开始报名，这是附一中舞蹈社证明自己、获取荣誉和资源的最佳舞台。',
  社团公开开放日: '学校要求所有社团举办一次对全校师生开放的活动，舞蹈社需要在维持“光鲜”形象和防止秘密泄露之间找到危险的平衡。',
  假期旅行: '利用短暂的假期，<user>决定组织一次核心成员的“团建”旅行，远离学校的环境可能会催生更放纵或更危险的行为。',
  社团扩张: '随着声名鹊起，<user>计划吸收更多新成员，但这将考验社团现有的同化体系，并增加秘密暴露的风险。',
  社团联动: '学生会长徐有渔提议，让舞蹈社与另一个热门社团（如武道社、篮球社）搞一次联谊活动，不同圈子的碰撞将带来不可预测的化学反应。',
};
const 随机事件ID列表 = Object.keys(主线事件库);

function 判断主线事件() {
  const isEventRunning = getvar('stat_data.世界.当前主线事件阶段', { defaults: 0 }) > 0;
  const isCooldown = getvar('stat_data.世界.主线事件冷却计数', { defaults: 0 }) > 0;
  const anyMemberAssimilationMet = getvar('stat_data.应禅溪.同化进度', { defaults: 0 }) >= 30 ||
                                 getvar('stat_data.颜竹笙.同化进度', { defaults: 0 }) >= 30 ||
                                 getvar('stat_data.徐有渔.同化进度', { defaults: 0 }) >= 30 ||
                                 getvar('stat_data.林珞然.同化进度', { defaults: 0 }) >= 30 ||
                                 getvar('stat_data.严喆珂.同化进度', { defaults: 0 }) >= 30 ||
                                 getvar('stat_data.俞弦.同化进度', { defaults: 0 }) >= 30;

  // --- 特定剧情事件：陈着股票爆雷 ---
  const chenZheEventTriggered = getvar('stat_data.世界.陈着爆雷事件已触发', { defaults: false });
  const currentDate = new Date();
  const triggerDate = new Date('2024-10-02');
